window.ScripturaLexicons.BDAG_PART_0172 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-01\" data-source=\"BDAG\" data-search=\"Ἰακώβ, ὁ nome próprio masculino indeclinável Jacó; patriarca; pai de José BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰακώβ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Jacó; patriarca; pai de José</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-02\" data-source=\"BDAG\" data-search=\"Ἰάκωβος, ου, ὁ nome próprio masculino Tiago; Jacó na forma helenizada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰάκωβος, ου, ὁ</td><td>nome próprio masculino</td><td>Tiago; Jacó na forma helenizada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-03\" data-source=\"BDAG\" data-search=\"ἴαμα, ατος, τό substantivo neutro cura; remédio; dom de cura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴαμα, ατος, τό</td><td>substantivo neutro</td><td>cura; remédio; dom de cura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-04\" data-source=\"BDAG\" data-search=\"Ἰαμβρῆς, ὁ nome próprio masculino Jambres BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰαμβρῆς, ὁ</td><td>nome próprio masculino</td><td>Jambres</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-05\" data-source=\"BDAG\" data-search=\"Ἰανναί, ὁ nome próprio masculino indeclinável Janai BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰανναί, ὁ</td><td>nome próprio masculino indeclinável</td><td>Janai</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-06\" data-source=\"BDAG\" data-search=\"Ἰάννης, ὁ nome próprio masculino Janes; mago egípcio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰάννης, ὁ</td><td>nome próprio masculino</td><td>Janes; mago egípcio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-07\" data-source=\"BDAG\" data-search=\"ἰάομαι verbo médio depoente curar; restaurar; libertar de males; perdoar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰάομαι</td><td>verbo médio depoente</td><td>curar; restaurar; libertar de males; perdoar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-08\" data-source=\"BDAG\" data-search=\"Ἰάρετ, ὁ nome próprio masculino indeclinável Jarede; pai de Enoque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰάρετ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Jarede; pai de Enoque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-09\" data-source=\"BDAG\" data-search=\"ἴασις, εως, ἡ substantivo feminino cura; restauração da saúde; perdão; libertação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴασις, εως, ἡ</td><td>substantivo feminino</td><td>cura; restauração da saúde; perdão; libertação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-10\" data-source=\"BDAG\" data-search=\"ἴασπις, ιδος, ἡ substantivo feminino (ocasionalmente masculino) jaspe; pedra preciosa opaca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴασπις, ιδος, ἡ</td><td>substantivo feminino (ocasionalmente masculino)</td><td>jaspe; pedra preciosa opaca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-11\" data-source=\"BDAG\" data-search=\"Ἰάσων, ονος, ὁ nome próprio masculino Jasom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰάσων, ονος, ὁ</td><td>nome próprio masculino</td><td>Jasom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-12\" data-source=\"BDAG\" data-search=\"ἰατρός, οῦ, ὁ substantivo masculino médico; curador; médico da alma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰατρός, οῦ, ὁ</td><td>substantivo masculino</td><td>médico; curador; médico da alma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-13\" data-source=\"BDAG\" data-search=\"Ἰαχίν, ὁ nome próprio masculino indeclinável Jaquim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰαχίν, ὁ</td><td>nome próprio masculino indeclinável</td><td>Jaquim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-14\" data-source=\"BDAG\" data-search=\"ιβ´ sinal numeral grego doze; décimo segundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ιβ´</td><td>sinal numeral grego</td><td>doze; décimo segundo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-15\" data-source=\"BDAG\" data-search=\"Ἰγνάτιος, ου, ὁ nome próprio masculino Inácio de Antioquia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰγνάτιος, ου, ὁ</td><td>nome próprio masculino</td><td>Inácio de Antioquia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-16\" data-source=\"BDAG\" data-search=\"ἴδε partícula; imperativo lexicalizado vê!; olhe!; eis; atenção! BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴδε</td><td>partícula; imperativo lexicalizado</td><td>vê!; olhe!; eis; atenção!</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-17\" data-source=\"BDAG\" data-search=\"ἰδέα, ας, ἡ substantivo feminino aparência exterior; aspecto; forma; espécie BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰδέα, ας, ἡ</td><td>substantivo feminino</td><td>aparência exterior; aspecto; forma; espécie</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-18\" data-source=\"BDAG\" data-search=\"ἴδιος, ία, ον adjetivo; substantivação e emprego adverbial próprio; particular; pertencente a alguém; privadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴδιος, ία, ον</td><td>adjetivo; substantivação e emprego adverbial</td><td>próprio; particular; pertencente a alguém; privadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-19\" data-source=\"BDAG\" data-search=\"ἰδίως advérbio de maneira particular; especialmente; individualmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰδίως</td><td>advérbio</td><td>de maneira particular; especialmente; individualmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0172-20\" data-source=\"BDAG\" data-search=\"ἰδιώτης, ου, ὁ substantivo masculino leigo; inexperiente; não especializado; pessoa de fora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰδιώτης, ου, ὁ</td><td>substantivo masculino</td><td>leigo; inexperiente; não especializado; pessoa de fora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0172-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰακώβ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável (יַעֲקֹב), «Jacó». Essa forma não helenizada do Antigo Testamento é reservada à escrita formal e especialmente ao patriarca (assim também os pseudoepígrafos; Fílon, por exemplo, Leg. Alleg. 3, 18; Sacrif. Abel. 5; Ebr. 82; Migr. Abr. 200; SibOr 2, 247; Justino; Melitão; também na magia, PGM 4, 1736; 1803, e na grafia <span class=\"greek\">Ἰακούβ</span> [IDefixWünsch 3, 2]. Diferentemente em Josefo, ver <span class=\"greek\">Ἰάκωβος</span>; ver Dssm., B 184, 3 [BS 282]; quanto às exceções, ver <span class=\"greek\">Ἰάκωβος</span> 4).</p><p class=\"entry-text\">① Filho de Isaque (marido de Lia e Raquel), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:34</a>; Jo 4:5s., 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:8</a>, 12, 14s., 46 (mas ver abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:13</a> (Ml 1:2s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a>, 20s.; 1Cl 4:8; 31:4; B 11:9 (citação de origem desconhecida); 13:4s.</p><p class=\"entry-text\">Da nação de Israel, descendentes de Jacó (Nm 23:7; Sir 23:12; Is 9:7; 40:27 e outros; Justino, D. 11, 5 <span class=\"greek\">γένος</span>; cf. 26:1 <span class=\"greek\">ὅσοι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">γεγέννηνται</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:26</a> (Is 59:20); talvez também em <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰ</span>., «casa de Jacó», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:46</a>. Também (Êx 19:3; Is 2:5; PsSol 7:10; Justino, D. 53, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:33</a>; cf. 1Cl 29:2 (Dt 32:9).</p><p class=\"entry-text\">A tríade Abraão, Isaque e Jacó (também em textos mágicos [ver <span class=\"greek\">Ἀβραάμ</span>] e inscrições funerárias, Sb 2034, 11; 3901, 12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:28</a>; B 8:4; IPhld 9:1; GJs 20:2 (não no papiro), <span class=\"greek\">σπέρμα</span> (Justino, D. 135, 5 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">σπέρμα</span>). Em especial, o Deus de Abraão, Isaque e Jacó (Êx 3:6; Justino, D. 11, 1 e outros; também na magia, PGM 4, 1231s.; IDefixWünsch 5, 2; 37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:13</a>; 7:32. — Cf. B 6:8 (Êx 33:1).</p><p class=\"entry-text\">② Pai de José, na genealogia de Jesus, Mt 1:15s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:23</a>, Códice D. — M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰάκωβος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Forma helenizada do nome anterior, W-S. §10, 3; EpArist 48; 49. Frequente em Josefo, até para o patriarca [ver <span class=\"greek\">Ἰακώβ</span>]. Na grafia <span class=\"greek\">Ἰάκουβος</span>, POxy 276, 5 [77 d.C.]; BGU 715 II, 11; 1Esd 9:48.) Tiago (quanto à história desse nome, ver OED, s.v. James).</p><p class=\"entry-text\">① Filho de Zebedeu, pescador galileu, irmão de João, membro dos Doze, executado por Herodes Agripa I não depois de 44 d.C.: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:21</a>; 10:2; 17:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:19</a>, 29; 3:17; 5:37; 9:2; 10:35, 41; 13:3; 14:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:10</a>; 6:14; 8:51; 9:28, 54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:13a</a>; 12:2; GEb 34, 60; Pápias (2:4). — E. Schwartz, Über d. Tod der Söhne Zeb., 1904; J. Blinzler e A. Böhling, NovT 5, ’62, 191–213.</p><p class=\"entry-text\">② Filho de Alfeu (ver <span class=\"greek\">Ἁλφαῖος</span>), também pertencente aos Doze, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:14</a>, variante de leitura (ver 6 abaixo); 3:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:13b</a>. Esse Tiago talvez seja idêntico ao seguinte.</p><p class=\"entry-text\">③ Filho de Maria, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:10</a> (ver B-D-F §162, 3), chamado em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:40</a> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μικρός</span>, «Tiago, o pequeno» ou «o mais jovem» (<span class=\"greek\">μικρός</span> 1ab. — T. Zahn, Forschungen VI, 1900, 345s.; 348ss.).</p><p class=\"entry-text\">④ Irmão do Senhor (Josefo, Ant. 20, 200), posteriormente dirigente da comunidade cristã de Jerusalém; confundido desde cedo com o da acepção 2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:19</a>; 2:9, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:17</a>; 15:13; 21:18; GHb 361, 7 (latim); provavelmente Pápias 2:4. Esse Tiago é certamente o referido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:1</a> (M. Meinertz, D. Jk u. sein Verf., 1905; A. Meyer, D. Rätsel des Jk, 1930); Jd 1; e talvez em GJs 25:1, no título e no subscrito.</p><p class=\"entry-text\">— G. Kittel, D. Stellg. des Jak. zu Judentum u. Heidenchristentum: ZNW 30, ’31, 145–57; D. geschichtl. Ort des Jk: ibid. 41, ’42, 71–105; K. Aland, D. Herrenbr. Jak. u. Jk: Neut. Entwürfe, ’79, 233–45; G. Kittel, D. Jak. u. die Apost. Väter: ZNW 43, ’50/51, 54–112; W. Prentice, em Studies in Roman Economic and Social Hist. in honor of A. Johnson, ’51, 144–51; P. Gaechter, Petrus u. seine Zeit, ’58, 258–310; D. Little, The Death of James: The Brother of Jesus, tese, Rice Univ., ’71; W. Pratscher, Der Herrenbruder Jakobus u. die Jakobustradition, ’87.</p><p class=\"entry-text\">⑤ Pai de um apóstolo chamado Judas, mencionado somente por Lucas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:16a</a>; At 1:13c.</p><p class=\"entry-text\">⑥ Na variante de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:14</a> (ver 2 acima), o cobrador de impostos chama-se Tiago (em lugar de Levi; ver F. Burkitt, JTS 28, 1927, 273s.). — H. Holtzmann, Jak. der Gerechte u. seine Namensbrüder: ZWT 23, 1880, 198–221; F. Maier, Z. Apostolizität des Jak. u. Jud.: BZ 4, 1906, 164–91; 255–66; H. Koch, Z. Jakobusfrage Gal 1:19: ZNW 33, ’34, 204–9. — EDNT; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴαμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Heródoto e outros, com o sentido «remédio».) Cura (Platão, Leg. 7 p. 790d; Luciano, Calumn. 17; SIG 1168, 2 <span class=\"greek\">ἰάματα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀπόλλωνος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀσκλαπιοῦ</span>; 24; 35; IGUR IV, 1702; cf. Jr 40:6; também ApcSed 10:6b p. 134, 7 Ja.). <span class=\"greek\">χαρίσματα</span> <span class=\"greek\">ἰαμάτων</span>, «dons (espirituais) de cura», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:9</a>, 28, 30; cf. <span class=\"greek\">ἰάματα</span>, B 3:4, variante de leitura (em lugar de <span class=\"greek\">ἱμάτια</span>; ver o final de <span class=\"greek\">ἱμάτιον</span>), Funk. — M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰαμβρῆς, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Jambres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:8</a>; ver <span class=\"greek\">Ἰάννης</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰανναί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável. Janai, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:24</a> (<span class=\"greek\">Ἰαννά</span>, variante de leitura).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰάννης, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Janes, mencionado com Jambres como um dos magos egípcios que (Êx 7:11ss.) se opuseram a Moisés diante do faraó, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:8</a>. Os nomes provêm da tradição judaica (Schürer III 781–83; M. Dibelius, Hdb., ad loc.; TestSol 25:4, de onde Numênio de Apameia [séc. II d.C.], em Eusébio, PE 9, 8, 1, os tomou). <span class=\"greek\">Μαμβρῆς</span> aparece como variante de <span class=\"greek\">Ἰαμβρῆς</span>, refletindo a variação dos manuscritos. Uma obra apócrifa judaica que trazia ambos os nomes desapareceu, restando somente o título (Schürer, loc. cit.).</p><p class=\"entry-text\">— R. James, JTS 2, 1901, 572ss.; Documento de Damasco (Kl. T. 167), 5, 19s. (cf. CD 5, 18s. e S. Schechter, Fragments of a Zadokite Work, 1910, pp. xxxvii e lixs.); Billerb. III 660–64; L. Grabbe, The Jannes-Jambres Tradition in Targum Pseudo-Jonathan and Its Date: JBL 98, ’79, 393–401; A. Pietersma, The Apochryphon of Jannes and Jambres the Magician—PChesterBeatty XVI (EPROR 119), ’94. — BHHW II, 802; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰάομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Verbo médio depoente: imperfeito <span class=\"greek\">ἰώμην</span>; futuro <span class=\"greek\">ἰάσομαι</span>; 1º aoristo <span class=\"greek\">ἰασάμην</span>. Formas passivas com significado passivo: 1º futuro <span class=\"greek\">ἰαθήσομαι</span>; 1º aoristo <span class=\"greek\">ἰάθην</span>; imperativo <span class=\"greek\">ἰαθήτω</span>; perfeito <span class=\"greek\">ἴαμαι</span> (B-D-F §311, 1) (Homero e posteriores; SIG 1168, 108; 113; 117; 1169, 7; PSI 665, 5 [séc. III a.C.]; BGU 1026 XXII, 15; LXX, En, TestSol; ApcrEzk P 1 verso 12; Fílon; Josefo, Ant. 9, 105; Justino, Taciano, Atenágoras).</p><p class=\"entry-text\">① Restituir a saúde a alguém depois de enfermidade física: curar, sarar, literalmente, com acusativo <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:17</a>; 6:19; 9 (no v. 2 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀσθενεῖς</span> é omitido em variante de leitura), 11, 42; 14:4; 22:51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:34</a>; 10:38; 28:8; 1Cl 59:4; AcPl BMM verso 11.</p><p class=\"entry-text\">Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>, 13; 15:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:7</a>; 8:47; 17:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:16</a>, Códice D; GJs 20:2 (4 na versão ampliada, ver de Strycker); é muito duvidoso AcPl BMM verso 18 (texto corrompido, texto de Sander: <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">αθι̣</span>[lacuna]). <span class=\"greek\">ἰαθῆναι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «ser curado de uma enfermidade»: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μάστιγος</span>, «do terrível sofrimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:29</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νόσων</span> <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:18</a>. <span class=\"greek\">ἰᾶσθαι</span> <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span>, «ser curado por meio de algo», B 8:6.</p><p class=\"entry-text\">② Livrar de males ou condições de vários tipos que ultrapassam as doenças físicas: restaurar, curar; extensão figurada de 1 (Élio Aristides 13 p. 273 D.; Juliano, Ep. 61, 424a, dos males da ignorância; Salústio 14 p. 28, 3 <span class=\"greek\">κακίαν</span>; Josefo, Ant. 2, 119 <span class=\"greek\">λύπην</span>).</p><p class=\"entry-text\">ⓐ Restaurar (<span class=\"greek\">ἰαθήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>, «a terra será restaurada», En 10:7), com acusativo <span class=\"greek\">τινά</span>, «alguém», do pecado e de suas consequências, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:27</a> (todos três Is 6:10); os quebrantados de coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a>, variante de leitura; B 14:9 (ambos Is 61:1).</p><p class=\"entry-text\">ⓑ Curar algo, com acusativo <span class=\"greek\">τὶ</span> (Filóstrato, Vi. Soph. 1, 22 p. 38, 9; cf. o provérbio em Heródoto 3, 53, 4; Tucídides 5, 65, 2; Apolônio de Rodes 4, 1081; Apiano, Ital. 5 §10; Bell. Civ. 1, 3 §9; Prov. Aesopi 91 P.: <span class=\"greek\">κακὸν</span> <span class=\"greek\">κακῷ</span> <span class=\"greek\">ἰᾶσθαι</span>), <span class=\"greek\">τὰ</span> <span class=\"greek\">ἁμαρτήματα</span>, «os pecados», Hv 1, 1, 9 (Apiano, Hann. 31 §131 <span class=\"greek\">ἁμάρτημα</span> <span class=\"greek\">ἰ</span>.); <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγνοήματα</span>, «os erros por ignorância», Hs 5, 7, 4; <span class=\"greek\">τὰ</span> <span class=\"greek\">προγεγονότα</span> <span class=\"greek\">πονηρά</span>, «todos os males anteriores», Hs 1, 3, 1; cf. Hs 9, 23, 5.</p><p class=\"entry-text\">Em uso absoluto, dos resultados do castigo divino ao qual Deus põe termo, 1Cl 56:7 (Jó 5:18). — Na passiva, do pecado: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:16</a>; 2Cl 9:7; Hs 9, 28, 5. A figura do pecado como ferida ou doença também é clara em <span class=\"greek\">ἵνα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χωλὸν</span> <span class=\"greek\">ἰαθῇ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:13</a>, e <span class=\"greek\">τῷ</span> <span class=\"greek\">μώλωπι</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἰάθημεν</span>, 1Cl 16:5; B 5:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:24</a> (todos três Is 53:5; cf. Taciano 43, 3). — DELG; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰάρετ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também <span class=\"greek\">Ἰαρέδ</span>, <span class=\"greek\">Ἰάρεδ</span>, <span class=\"greek\">Ἰάρεθ</span>; indeclinável; יֶרֶד, na pausa יָרֶד.) Jarede, pai de Enoque (Gn 5:15, 18; 1Cr 1:2; En 106:13; <span class=\"greek\">Ἰάρεδ</span> em todas essas passagens, mas <span class=\"greek\">Ἰάρετ</span> como variante em Gn 5:18 [A. Rahlfs, Genesis, 1926]. — Josefo, Ant. 1, 79; 84, <span class=\"greek\">Ἰάρεδος</span>, <span class=\"greek\">ου</span>), na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:37</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(De <span class=\"greek\">ἰάομαι</span>; Arquíloco [séc. VII a.C.] e outros; SIG 244 I, 53; LXX; En 10:7; TestJob 38:8; TestZeb 9:8; ApcSed 10:6; Fílon, Josefo; Justino, A II, 13, 4; também [em lugar de <span class=\"greek\">ἰάθημεν</span>, Is 53:5], D. 17, 1; 95, 3; e [sobre Is 11:2], D. 39, 2).</p><p class=\"entry-text\">① Restabelecimento da saúde após doença física: cura, tratamento, em sentido literal (Hipócrates, Platão e outros; LXX; Josefo, Ant. 7, 294), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:7</a>, variante de leitura. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἴασιν</span>, «para cura», isto é, «para curar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:30</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰ</span>., «o milagre da cura», v. 22. <span class=\"greek\">ἰάσεις</span> <span class=\"greek\">ἀποτελεῖν</span> (ver Vécio Valente sob 2), «realizar curas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:32</a>; <span class=\"greek\">δέησις</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰ</span>., «oração pela cura», B 12:7.</p><p class=\"entry-text\">② Libertação de males ou condições que vão além de enfermidades físicas: cura, libertação; extensão figurada da acepção 1 (Platão, Leg. 9, 862c <span class=\"greek\">ἴασις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span>; Luciano, Jupp. Trag. 28; Alcífron 3, 13, 2; Vécio Valente 190, 30 <span class=\"greek\">τῶν</span> <span class=\"greek\">φαύλων</span> <span class=\"greek\">ἴασιν</span> <span class=\"greek\">ἀποτελεῖ</span>; Sir 43:22; Fílon, Leg. All. 2, 79 <span class=\"greek\">ἴ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάθους</span>; Josefo, Ant. 5, 41), do perdão dos pecados (Arriano, Anab. 7, 29, 2 <span class=\"greek\">μόνη</span> <span class=\"greek\">ἴασις</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἁμαρτόντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δῆλον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μεταγινώσκοντα</span>, «a única cura do pecado é o pecador confessá-lo e demonstrar arrependimento»; Hiérocles 11, 441 <span class=\"greek\">ἰ</span>. <span class=\"greek\">γίνεται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προημαρτημένων</span>; Sir 28:3; ver também <span class=\"greek\">ἰάομαι</span> 2).</p><p class=\"entry-text\"><span class=\"greek\">ἴασιν</span> <span class=\"greek\">δοῦναι</span>, «conceder perdão», Hm 4, 1, 11; Hs 5, 7, 3s.; <span class=\"greek\">ἴασιν</span> <span class=\"greek\">δοῦναί</span> <span class=\"greek\">τινι</span>, «conceder perdão a alguém», Hs 7:4. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἴασιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁμαρτήμασίν</span> <span class=\"greek\">τινος</span>, «perdoar os pecados de alguém», Hm 12, 6, 2. <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">ἴασιν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span>, «receber do Senhor o perdão dos pecados», Hs 8, 11, 3 (<span class=\"greek\">λαμβ</span>. <span class=\"greek\">ἴ</span>., como Fílon, Post. Cai. 10). — DELG, s.v. <span class=\"greek\">ἰάομαι</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴασπις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino (ocasionalmente masculino)</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Platão e outros; SIG2 587, 87s. [séc. IV a.C.]; PGM 12, 203 <span class=\"greek\">ἴασπιν</span>; LXX; TestSol; Josefo, Bell. 5, 234; Ant. 3, 168. Ocasionalmente também masculino, por exemplo Petosíris, Fgm. 29.) Jaspe, pedra preciosa encontrada em diversas cores, predominantemente avermelhada; às vezes verde (Cyranides p. 23, 22 <span class=\"greek\">λίθος</span> <span class=\"greek\">χλωρός</span>), castanha, azul, amarela e branca. Na Antiguidade, a designação não se restringia à variedade de quartzo hoje chamada jaspe, mas podia abranger qualquer pedra preciosa opaca.</p><p class=\"entry-text\">Ap 21:18s. Com <span class=\"greek\">λίθος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:3</a> (TestSol C 11:8). <span class=\"greek\">λίθος</span> <span class=\"greek\">ἴασπις</span> <span class=\"greek\">κρυσταλλίζων</span>, «pedra de jaspe cristalino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:11</a> (cf. Is 54:12); talvez se trate da opala; segundo alguns, do diamante. Ver <span class=\"greek\">ἀμέθυστος</span>. — DELG; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰάσων, ονος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Frequentemente atestado, também na LXX; EpArist 49; Josefo. Era prática comum entre judeus empregar o nome puramente grego <span class=\"greek\">Ἰάσων</span> em substituição ao nome hebraico-grego <span class=\"greek\">Ἰησοῦς</span>: Dssm., B 184, 1 [BS 315, 2]; B-D-F §53, 2d.) Jasom.</p><p class=\"entry-text\">① Hospedeiro de Paulo e Silas em Tessalônica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5-7\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:5–7</a>, 9.</p><p class=\"entry-text\">② Pessoa que envia saudações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:21</a>, dificilmente a mesma da acepção 1.</p><p class=\"entry-text\">③ <span class=\"greek\">Ἰάσονι</span> aparece por <span class=\"greek\">Μνάσωνι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:16</a>, variante de leitura. — LGPN I; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰατρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἰάομαι</span>; Homero e posteriores.)</p><p class=\"entry-text\">① Pessoa que se ocupa da cura de enfermidades físicas: médico, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:31</a> (cf. sobre essas passagens Plutarco, Mor. 230s.; Phocion 746 [10, 5]; Estobeu, Floril. III p. 462, 14 H., <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἰατρὸς</span> <span class=\"greek\">ὑγιείας</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">ποιητικὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑγιαίνουσι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διατριβὴν</span> <span class=\"greek\">ποιεῖται</span>, «pois nenhum médico capaz de produzir curas passa o tempo entre pessoas saudáveis»); Ox 1, reto, 9–14 (ASyn. 33, 85; ver GTh 31; cf. Díon Crisóstomo 8 [9], 4 <span class=\"greek\">νοσοῦντες</span> <span class=\"greek\">ἐπιδημοῦντος</span> <span class=\"greek\">ἰατροῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσῄεσαν</span>, dito ironicamente de enfermos que não queriam consultar um médico residente); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:26</a> (Sb 8266, 13ss. [161/160 a.C.]: quando os médicos se recusam a ajudar, o deus Amenótis intervém com um milagre).</p><p class=\"entry-text\"><span class=\"greek\">ἰατροῖς</span> <span class=\"greek\">προσαναλίσκειν</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">βίον</span>, «gastar todo o dinheiro com médicos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:43</a>, variante de leitura (PStras 73, 18s., honorários médicos de 20 dracmas; Diodoro Sículo 32, 11, 3, um médico <span class=\"greek\">διπλοῦν</span> <span class=\"greek\">ἀπῄτει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθόν</span>, «exigia o dobro dos honorários». Mas alguns médicos eram homenageados por não receber remuneração; ver F. Kudlien, em Sozialmassnahmen und Fürsorge, org. H. Kloft, ’88, 90–92; ver também Danker, Benefactor, n.os 1–4, para avaliação favorável).</p><p class=\"entry-text\">A profissão de médico é atribuída a alguém chamado Lucas, Cl 4:14 (Heráclides Pôntico, Fgm. 118 W. <span class=\"greek\">Ἀσκληπιάδης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἰ</span>.; Estrabão 10, 5, 6 p. 486 <span class=\"greek\">Ἐρασίστρατος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἰ</span>.; Sb 8327 [inscrição do séc. II d.C.] <span class=\"greek\">Ἀπολλώνιος</span> <span class=\"greek\">ἰατρός</span>). Num provérbio (ver Jülicher, Gleichn. 172s.; E. Klostermann e F. Hauck, ad loc.): <span class=\"greek\">ἰατρὲ</span> <span class=\"greek\">θεράπευσον</span> <span class=\"greek\">σεαυτόν</span>, «médico, cura-te a ti mesmo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:23</a> (Eurípides, Fgm. 1086 Nauck2 <span class=\"greek\">ἄλλων</span> <span class=\"greek\">ἰατρὸς</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἕλκεσιν</span> <span class=\"greek\">βρύων</span>; Esopo, Fab. 289 P. = H. 78 e 78b = Bábrio 120, <span class=\"greek\">πῶς</span> <span class=\"greek\">ἄλλον</span> <span class=\"greek\">ἰήσῃ</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">σαυτὸν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σῴζεις</span>). — Pápias (3:2); AcPl Ha 5, 34. Para IEph 7:2, ver 2.</p><p class=\"entry-text\">② Pessoa que se ocupa de males supracorporais: médico (da alma) (Diógenes Laércio 3, 45: epigrama que chama Platão de <span class=\"greek\">ἰητὴρ</span> <span class=\"greek\">ψυχῆς</span>; escólio a Platão 227a <span class=\"greek\">ὁ</span> <span class=\"greek\">Σωκράτης</span> <span class=\"greek\">ἰατρὸς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ψυχήν</span>; Diodoro Sículo 34+35 Fgm. 17, 1 <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κάλλιστος</span> <span class=\"greek\">ἰατρὸς</span> <span class=\"greek\">χρόνος</span>; Fílon, Spec. Leg. 2, 31 <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἁμαρτημάτων</span>). De Deus (ver D. Rahnenführer, Das Testament des Hiob, ZNW 62, ’71, 76; Aristófanes, Av. 584 e Licofron 1207; 1377 sobre Apolo; Simplício em Epicteto, p. 41, 51, Deus como <span class=\"greek\">ἰατρός</span>; Élio Aristides 47, 57 K. = 23 p. 459 D., Asclépio como <span class=\"greek\">ἀληθινὸς</span> <span class=\"greek\">ἰατρός</span>), Dg 9:6.</p><p class=\"entry-text\">De Jesus Cristo: <span class=\"greek\">ἰ</span>. <span class=\"greek\">σαρκικὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνευματικός</span>, «médico do corpo e da alma» (ou «médico que é carne e espírito»), IEph 7:2. Ver J. Ott, D. Bezeichnung Christi als <span class=\"greek\">ἰατρός</span> in d. urchristl. Literatur: Der Katholik 90, 1910, 457s.; A. von Harnack, Mission4 I, 1923, 129ss.; RAC I 720–25. Sobre a prática médica no mundo greco-romano, ver ANRW II Principat 37, 1–3, 93–96. — B. 308; DELG, s.v. <span class=\"greek\">ἰάομαι</span>; M-M; SEG XXXIX, 1804; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰαχίν, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável. Jaquim, na genealogia de Jesus, Lc 3:23ss., Códice D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ιβ´</h1><div class=\"entry-meta\"><span>sinal numeral grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Numeral 12 (nos manuscritos, em lugar de <span class=\"greek\">δώδεκα</span>, como em Josefo, C. Ap. 1, 122; Melitão, P. 83, 627 [B]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:7</a>, Códice D. No pós-escrito de Marcos no grupo Ferrar (ver <span class=\"greek\">Ῥωμαϊστί</span>): <span class=\"greek\">ἐγράφη</span> <span class=\"greek\">ιβ</span>´ <span class=\"greek\">ἔτη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναλήψεως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span>, «foi escrito no décimo segundo ano após a ascensão do Senhor»; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:26</a>, Códice D; GJs 1:1; 6:3; 8:2s.; «décimo segundo» (<span class=\"greek\">δωδεκάτη</span>), Hm 12, sobrescrito.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰγνάτιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Sobre o nome, ver Hdb., Ergänzungsband, 1923, 189. Além dos exemplos de tal grafia ali apresentados, ver também Sb 8802b, 6 [82/83 d.C.]; 7662, 23 [séc. II d.C.].) Inácio, supervisor eclesiástico (bispo) de Antioquia, IEph, IMg, ITr, IRo, IPhld, ISm, IPol, nos títulos; Pol 9:1; 13:1s.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴδε</h1><div class=\"entry-meta\"><span>partícula; imperativo lexicalizado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Sobre a acentuação, ver o começo de <span class=\"greek\">εἶδον</span>.) Propriamente imperativo de <span class=\"greek\">εἶδον</span>, porém fixado como partícula e, por isso, também usado quando mais de uma pessoa é interpelada e quando o que se deve observar está no nominativo (B-D-F §144; esse emprego do imperativo [LXX; Justino, A I, 50, 3 em lugar de <span class=\"greek\">ἰδού</span>, Is 52:13] inicia-se em Homero; ver Kühner-G. I 84, 4). «Vê!»; geralmente no início da oração, mas por vezes no meio (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:26</a>). Serve para:</p><p class=\"entry-text\">① Indicar algo a que o falante deseja atrair a atenção: «olha!», «vê!» (Gn 27:6; Sir 28:24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:20</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:24</a>; 11:21; 13:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:14</a>; 18:21; B 8:1; 12:10. <span class=\"greek\">ἴ</span>. <span class=\"greek\">οὖν</span>, B 6:14; 15:7, variante de leitura. Seguido de pergunta indireta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:36</a>; cf. 16:29; 19:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:2</a>; B 12:11. Por <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:17</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:3</a>, variante (ver B. Metzger, A Textual Commentary, ’71, 507, 681s.). Seguido de <span class=\"greek\">εἰ</span>: «veja se», Hm 11:18ab.</p><p class=\"entry-text\">② Introduzir algo inesperado: «repare!», «presta atenção!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:26</a>; 7:26; 11:3; 12:19.</p><p class=\"entry-text\">③ Indicar lugar ou pessoa: «aqui está/estão», como o francês voici. <span class=\"greek\">ἴ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span>, «aqui é o lugar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:6</a>. <span class=\"greek\">ἴ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀδελφοί</span> <span class=\"greek\">μου</span>, «aqui estão minha mãe e meus irmãos» (ou «irmãos e irmãs»? ver <span class=\"greek\">ἀδελφός</span> 1; cf. <span class=\"greek\">ἴδε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">σου</span>, PsSol 11:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:34</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:20</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:29</a>, 36, 47; 19:14, 26. Ver G. Dalman, Jesus-Jeshua (trad. P. Levertoff), 1929, 201–3. Com advérbio de lugar, <span class=\"greek\">ἴδε</span> <span class=\"greek\">ὧδε</span> … <span class=\"greek\">ἴ</span>. <span class=\"greek\">ἐκεῖ</span>, «aqui está ... lá está», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:21</a>.</p><p class=\"entry-text\">④ Com perda evidente do sentido fundamental, como em nossa fala coloquial: «veja!», «preste atenção!».</p><p class=\"entry-text\">ⓐ (Escólio a Platão 130c: <span class=\"greek\">Ἀλκιβιάδης</span>, <span class=\"greek\">ἴδε</span>, <span class=\"greek\">τί</span> <span class=\"greek\">λέγει</span>, «ouve».) <span class=\"greek\">ἴ</span>. <span class=\"greek\">νῦν</span> <span class=\"greek\">ἠκούσατε</span>, «vejam, agora ouvistes», isto é, «pronto, agora ouvistes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:65</a>. <span class=\"greek\">ἴδε</span> <span class=\"greek\">πόσα</span> <span class=\"greek\">σου</span> <span class=\"greek\">κατηγοροῦσιν</span>, «escuta quantas acusações fazem contra ti», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:4</a>; <span class=\"greek\">ἴ</span>. <span class=\"greek\">Ἠλίαν</span> <span class=\"greek\">φωνεῖ</span>, «ouve, ele chama Elias», v. 35. <span class=\"greek\">ἴδε</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">τότε</span> <span class=\"greek\">καλῶς</span> <span class=\"greek\">καταπαυόμενοι</span> <span class=\"greek\">ἁγιάσομεν</span> <span class=\"greek\">αὐτήν</span>, <span class=\"greek\">ὅτε</span> …, «presta atenção (ao que isto significa)! Só poderemos santificar (o sábado) em verdadeiro repouso quando...», B 15:7.</p><p class=\"entry-text\">ⓑ Simplesmente «aqui»: <span class=\"greek\">ἴ</span>. <span class=\"greek\">ἔχεις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σόν</span>, «aqui tens o que é teu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:25</a>. Ver bibliografia s.v. <span class=\"greek\">ἰδού</span> 2, especialmente Fiedler; ver também <span class=\"greek\">ὁράω</span>. — M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰδέα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(A forma <span class=\"greek\">εἰδέα</span> é frequente no grego tardio; Píndaro, Heródoto e outros; papiros, LXX, TestAbr; TestBenj 10:1 [de Jonge; <span class=\"greek\">εἰδέαν</span> em Ch.]; AscIs 3:13 [papiro, coluna IX, 3 <span class=\"greek\">ἡ</span> <span class=\"greek\">εἰδέα</span>]; 4:4 [papiro, coluna XIV, 13s. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">εἰδέᾳ</span>]; Fílon, Josefo, Justino, Atenágoras. — C. Ritter sobre <span class=\"greek\">εἶδος</span>).</p><p class=\"entry-text\">① Aparência exterior de alguma coisa: aspecto, com destaque para as características físicas (em contraste com <span class=\"greek\">μορφή</span>, frequentemente empregado, por exemplo, associado à sugestão de posição ou à impressão que produz, como <span class=\"greek\">μορφὴ</span> <span class=\"greek\">θεοῦ</span> e <span class=\"greek\">μορφὴ</span> <span class=\"greek\">δούλου</span>, Fp 2:6s.) (Teógnis, Píndaro e outros; Artemidoro 2, 44 <span class=\"greek\">φαίνονται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ἰδέᾳ</span> [variante <span class=\"greek\">εἰδέᾳ</span>] <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μορφῇ</span>, «os deuses se mostram com a aparência e o aspecto dos seres humanos»; POxy 1277, 10; Gn 5:3; EpJer 62; 2Mc 3:16; TestAbr A 11 p. 89, 4 [Stone p. 26]; TestBenj 10:1; Josefo, Bell. 3, 508; Ant. 8, 177; Justino, A I, 62, 3 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰδέᾳ</span> <span class=\"greek\">πυρός</span> e outros), Hs 9, 17, 1s.</p><p class=\"entry-text\"><span class=\"greek\">ἡ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἱλαρὰ</span> <span class=\"greek\">ἦν</span>, «sua aparência era agradável», Hs 6, 1, 6. <span class=\"greek\">κατηφὴς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰ</span>., «abatido na aparência», Hv 1, 2, 3; cf. Hs 6, 2, 5; 9, 3, 1. <span class=\"greek\">ἠλλοιώθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">αὐτοῦ</span>, «sua aparência mudou», Hv 5:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:29</a>, Códice D. <span class=\"greek\">ἄλλην</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἔχειν</span>, «ter aparência diferente», Hs 9, 1, 4. A tradução «rosto» (cf. Diodoro Sículo 3, 8, dos etíopes, <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἰδέαις</span> <span class=\"greek\">σίμοι</span>; talvez Plutarco, Flamin. 369 [1, 1]; Field, n. 22) provavelmente cabe em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:3</a>, variante de leitura (por <span class=\"greek\">εἰδέα</span>), e Hv 1, 2, 3; Hs 6, 1, 6; ver <span class=\"greek\">εἰδέα</span>.</p><p class=\"entry-text\">② Variedade de alguma coisa: forma, espécie, tipo (Aristófanes, Ran. 384 <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">ὕμνων</span> <span class=\"greek\">ἰδέα</span>; Tucídides 1, 109, 1; 3, 102, 7; Apiano, Mithrid. 22 §87 <span class=\"greek\">συμφορῶν</span> <span class=\"greek\">ἰδέαι</span> <span class=\"greek\">ποικίλαι</span>, «diversos tipos de infortúnio», Bell. Civ. 4, 14 §53; 4Mc 1:14, 18; Fílon, Op. M. 22; Praem. 90; Josefo, Ant. 15, 416), <span class=\"greek\">ἄλλαις</span> <span class=\"greek\">βασάνων</span> <span class=\"greek\">ἰδέαις</span>, «com outras espécies de tormento», MPol 2:4 (cf. Tucídides 3, 81, 5 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">θανάτου</span>). — Ver também <span class=\"greek\">εἰδέα</span>. — B. 1212; DELG, s.v. <span class=\"greek\">ἰδεῖν</span>; M-M; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴδιος, ία, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivação e emprego adverbial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores; ver B-D-F §286; W-S. §22, 17; Rob. 691s.; Mlt-Turner 191s. — Quanto à grafia <span class=\"greek\">ἵδιος</span>, ver <span class=\"greek\">ὀλίγος</span>.)</p><p class=\"entry-text\">① Referente a algo que pertence à própria pessoa ou lhe diz respeito: próprio, seu próprio.</p><p class=\"entry-text\">ⓐ Em contraste com o que é propriedade pública ou pertence a outro: privado, pertencente exclusivamente à própria pessoa (em oposição a <span class=\"greek\">κοινός</span>, como Platão, Pol. 7, 535b; Apiano, Bell. Civ. 5, 41 §171; Atenágoras 25, 4). <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">τι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπαρχόντων</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἔλεγεν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">εἶναι</span>, «ninguém afirmava que algo do que possuía era propriedade privada», ou «ninguém reivindicava a posse exclusiva de bens particulares», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:32</a>; cf. D 4:8.</p><p class=\"entry-text\">ⓑ Em relação a circunstância ou condição pertencente a um indivíduo (em oposição a <span class=\"greek\">ἀλλότριος</span>): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">δύναμιν</span>, «conforme a capacidade de cada um» (em contraste com a dos outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:15</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ζητεῖ</span>, «busca a própria glória», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:18</a>; cf. 5:18, 43. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">πόλιν</span>, «cada qual à sua cidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:3</a>, variante (por <span class=\"greek\">ἑαυτοῦ</span>); semelhante em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:1</a> (relativo à ida de Jesus à sua terra); cf. Dg 5:2.</p><p class=\"entry-text\">Cristo <span class=\"greek\">ἐλευθερώσῃ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">σαρκός</span>, «liberta toda carne por meio de sua própria carne», AcPlCor 2:6; cf. v. 16. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">διαλέκτῳ</span> <span class=\"greek\">ἡμῶν</span>, «cada um em nosso próprio idioma», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:8</a>; cf. 1:19 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">διαλέκτῳ</span> <span class=\"greek\">αὐτῶν</span>, «no idioma próprio deles»; sem pronome, 2:6 (Taciano 26, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">αὐτῆς</span> … <span class=\"greek\">λέξιν</span>). <span class=\"greek\">ἰδίᾳ</span> <span class=\"greek\">δυνάμει</span>, «por poder próprio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:12</a>; cf. 28:30. <span class=\"greek\">τἡν</span> <span class=\"greek\">ἰ</span>. (<span class=\"greek\">δικαιοσύνην</span>), «a própria (justiça)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:3</a>; cf. 11:24; 14:4s.</p><p class=\"entry-text\"><span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἴ</span>. <span class=\"greek\">μισθὸν</span> <span class=\"greek\">λήμψεται</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἴ</span>. <span class=\"greek\">κόπον</span>, «cada um receberá salário proporcional ao próprio trabalho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:8</a>. <span class=\"greek\">ἑκάστη</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἄνδρα</span>, «cada mulher o próprio marido», 7:2 (Diógenes Laércio 8, 43 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">πορεύεσθαι</span>). <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">χάρισμα</span>, «cada um possui seu próprio dom», 7:7. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">δεῖπνον</span> <span class=\"greek\">προλαμβάνει</span> (ver <span class=\"greek\">προλαμβάνω</span> 1c), «cada um se antecipa a comer a própria ceia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:21</a> (Eratóstenes: 241 Fgm. 16 Jac., sobre a festa denominada Lagynophoria: <span class=\"greek\">τὰ</span> <span class=\"greek\">κομισθέντα</span> <span class=\"greek\">αὑτοῖς</span> <span class=\"greek\">δειπνοῦσι</span> <span class=\"greek\">κατακλιθέντες</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">λαγύνου</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὑτῶν</span> <span class=\"greek\">φέροντες</span> <span class=\"greek\">πίνουσιν</span>, «comem reclinados os alimentos que lhes foram trazidos ... e cada um bebe de um jarro que ele próprio trouxe». Avaliação: <span class=\"greek\">συνοίκια</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ῥυπαρά</span>· <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σύνοδον</span> <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">παμμιγοῦς</span> <span class=\"greek\">ὄχλου</span>, «que banquete desagradável; evidentemente é uma reunião de gente de toda espécie»); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:7</a>; 15:38. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴ</span>. <span class=\"greek\">φορτίον</span> <span class=\"greek\">βαστάσει</span>, «cada um levará sua própria carga», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:5</a>. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:10</a>; 7:27; 9:12; 13:12. — Quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:44</a>, ver 2 e 3b.</p><p class=\"entry-text\">② Referente a conexão notável ou relação exclusiva: próprio, com ênfase quando falado ou grafado em itálico. <span class=\"greek\">κοπιῶμεν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">χερσίν</span>, «trabalhamos com as próprias mãos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:12</a> (primeira pessoa; cf. UPZ 13, 14 [158 a.C.] <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφοῦ</span> <span class=\"greek\">ἰδίου</span>, «estou com meu próprio irmão»; TestJob 34:3 <span class=\"greek\">ἀναχωρήσωμεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">χώρας</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ὀφθαλμῷ</span>, «em teu próprio olho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:17</a> (aqui a firmeza dos ortodoxos contrasta com a perda de rumo dos que são desencaminhados pelo erro). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:7</a> (a autoridade de Deus contrasta fortemente com o interesse dos apóstolos em fixar um calendário de acontecimentos).</p><p class=\"entry-text\"><span class=\"greek\">ἰ</span>. <span class=\"greek\">θέλημα</span>, «vontade própria», e <span class=\"greek\">ἰδία</span> <span class=\"greek\">καρδία</span>, «coração ou mente própria», 1Co 7:37ab, contrapõem-se a <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ἀνάγκην</span>, «não estando sob coação»; por isso <span class=\"greek\">ἰ</span>. não equivale simplesmente ao genitivo possessivo da expressão <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτοῦ</span>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:18</a>, <span class=\"greek\">ἰ</span>. realça o absurdo de pecar contra o próprio corpo. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:34</a> (o narrador aparentemente sugere que o samaritano rico possuía mais de um animal, mas pôs o seu próprio ao serviço do viajante ferido). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἐξέραμα</span>, «ao próprio vômito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:22</a> (cf. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">ἔμετον</span>, Pv 26:11), intensificando a repulsa.</p><p class=\"entry-text\">Alguns incluiriam aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:44</a> (ver final da acepção 1). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἀγρόν</span>, «para o próprio campo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:5</a> (o convidado grosseiro prefere os confortos de sua própria propriedade). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:34b</a> (seguidores próximos de Jesus em contraste com a multidão). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:19</a> (com destaque para o caráter esotérico de disputas sectárias). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:14</a> (contraste não entre espécies de desejo, mas entre origens da tentação: quem sucumbe só pode culpar a si próprio). <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span>, «por seu próprio sangue», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:28</a> (assim, NRSV, nota marginal; cf. a expressão SIG 547, 37; 1068, 16 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span>, frequentemente associada aos presentes de benfeitores generosos, ver 4b. Que o «sangue» seria associado a Jesus ficaria perfeitamente claro ao público de Lucas).</p><p class=\"entry-text\">③ Referente a uma pessoa, em substituição a pronome: seu, próprio. Algumas passagens citadas em 2 talvez pertençam aqui. <span class=\"greek\">ἴ</span>. substitui o genitivo de <span class=\"greek\">αὐτός</span>, o pronome possessivo ou o genitivo possessivo de <span class=\"greek\">ἑαυτοῦ</span>, <span class=\"greek\">ἑαυτῶν</span> (uso encontrado em escritores helenísticos [Schmidt 369], inscrições áticas [Meisterhans3-Schw. 235] e magnesianas [Thieme 28s.], papiros [Kuhring — ver início de <span class=\"greek\">ἀνά</span> — 14; Mayser II/2, 73s.]. Ver também Dssm., B 120s. [BS 123s.], e, contra ele, Mlt. 87–91).</p><p class=\"entry-text\">A LXX emprega muitas vezes <span class=\"greek\">ἴ</span>. sem ênfase para traduzir simplesmente o sufixo pessoal hebraico (Gn 47:18; Dt 15:2; Jó 2:11; 7:10, 13; Pv 6:2 e outros), mas às vezes também o emprega sem fundamento no texto original (Jó 24:12; Pv 9:12; 22:7; 27:15). Em Dn 1:10, onde a LXX tem <span class=\"greek\">ἴ</span>., Teodocião usa <span class=\"greek\">μου</span>. 1Esd 5:8 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">πόλιν</span> = 2Esd 2:1 <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">αὐτοῦ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:1</a> é formalmente semelhante, mas sua posição narrativa sugere enquadrá-lo em 1.</p><p class=\"entry-text\">ⓐ Com a segunda pessoa (Josefo, Bell. 6, 346 <span class=\"greek\">ἰδίαις</span> <span class=\"greek\">χερσίν</span>, «com tuas próprias mãos»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:22</a> (cf. v. 28 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">γυναῖκας</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:1</a>.</p><p class=\"entry-text\">ⓑ Com a terceira pessoa: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδίᾳ</span> <span class=\"greek\">πατρίδι</span>, «em sua própria terra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:44</a> (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πατρίδι</span> <span class=\"greek\">αὐτοῦ</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:24</a>, mas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:44</a> tem formulação ligeiramente diferente e talvez pertença, portanto, a 1b acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:14</a>; 15:20, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:41</a> (UPZ 13, ver 2 acima: <span class=\"greek\">ἀδ</span>. <span class=\"greek\">ἴ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:19</a>; 24:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:5</a>, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:5</a>; MPol 17:3; AcPl Ha 3, 21; 4, 27 (contexto incerto); <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">πλάσμα</span>, «sua própria criatura», AcPlCor 2:12, 1; <span class=\"greek\">ἴδιον</span> <span class=\"greek\">χωρίον</span>, «terreno próprio», Pápias (3:3).</p><p class=\"entry-text\">④ Substantivado: pessoa ou coisa associada a uma entidade.</p><p class=\"entry-text\">ⓐ Companheiros, parentes. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἴδιοι</span>, «os seus» (companheiros em batalha: Polieno, Exc. 14, 20; SIG 709, 19; 22; 2Mc 12:22; Josefo, Bell. 1, 42; Ant. 12, 405; compatriotas: ViHab 5 [p. 86, 7 Sch.]; Fílon, Mos. 1, 177), «companheiros cristãos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:23</a>; 24:23 (Justino, D. 121, 3). Os discípulos (por exemplo, de filósofo: Epicteto 3, 8, 7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:1</a>. Parentes (BGU 37; POxy 932; PFay 110; 111; 112; 116; 122 e outros; Vécio Valente 70, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἰδίων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φίλων</span>; Sir 11:34; Justino, A II, 7, 2 <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἰδίοις</span> … <span class=\"greek\">Νῶε</span> e D. 138, 2 <span class=\"greek\">Νῶε</span> … <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:11b</a> (também assim são chamados os adoradores de uma divindade: Herm. Wr. 1, 31). — No singular, <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15:19</a>, variante de leitura (ver b abaixo).</p><p class=\"entry-text\">ⓑ Lar, posses. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span>, «casa, lar» (Políbio 2, 57, 5; 3, 99, 4; Apiano, Iber. 23; Peripl. Eryth. 65 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span>; POxy 4, 9s. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνωτέρα</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἴδια</span> <span class=\"greek\">γεινώσκει</span>; 487, 18; Et 5:10; 6:12; 1Esd 6:31 [<span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <span class=\"greek\">αὐτοῦ</span> = 2Esd 6:11 <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">αὐτοῦ</span>]; 3Mc 6:27, 37; 7:8; Josefo, Ant. 8, 405; 416; Bell. 1, 666; 4, 528), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:32</a> (E. Fascher, ZNW 39, ’41, 171–230); 19:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:18</a>, Códice D; 14:18, variante; 21:6; AcPl Ha 8, 5.</p><p class=\"entry-text\">Muitos (por exemplo, Goodsp., Probs. 87s.; 94–96; Field, Notes 84; RSV, mas não Bultmann 34s.; NRSV) preferem esse sentido para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:11a</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:28</a>; outra possibilidade em ambas é «propriedade, bens» (POxy 489, 4; 490, 3; 491, 3; 492, 4 e outros). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span>, «de suas próprias reservas abundantes» (frequentemente em inscrições, por exemplo de Magnésia e Priene, também SIG 547, 37; 1068, 16 [em tais inscrições, destaca-se a generosidade de oficiais que usam os próprios recursos para suprir necessidades públicas]; Josefo, Ant. 12, 158), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:44</a>.</p><p class=\"entry-text\">O singular também pode ocorrer nesse sentido, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> (SIG 1257, 3; BGU 1118, 31 [22 a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15:19</a> (variante <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span>, ver a acima). — <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span>, «os próprios negócios» (Xenofonte, Mem. 3, 4, 12; 2Mc 9:20; 11:23, variante, 26, 29), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:11</a>; aqui <span class=\"greek\">πράσσειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> = «cuidar da própria vida». — Jd 6, da esfera que propriamente cabe a alguém.</p><p class=\"entry-text\">⑤ Referente a estar só ou apartado: sozinho, em particular, privadamente; emprego adverbial <span class=\"greek\">ἰδίᾳ</span> (Aristófanes, Tucídides; Diodoro Sículo 20, 21, 5 e outros; inscrições, papiros, 2Mc 4:34; Fílon; Josefo, Bell. 4, 224; C. Ap. 1, 225; Atenágoras 8, 1s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:11</a>; IMg 7:1. — <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> (Mácon, Fgm. 11, v. 121 [em Ateneu 8, 349b]; Políbio 4, 84, 8; Diodoro Sículo 1, 21, 6; também inscrições [SIG 1157, 12 <span class=\"greek\">καὶ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">κοινὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">ἑκάστῳ</span> e outros]; 2Mc 4:5; 14:21; JosAs 7:1; Fílon, Sacr. Abel. 136; Justino, D. 5, 2), «em particular», «a sós» (em oposição a <span class=\"greek\">κοινῇ</span>: Josefo, Ant. 4, 310), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:13</a>, 23; 17:1, 19; 20:17; 24:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:34a</a>; 6:31s.; 7:33 (Diodoro Sículo 18, 49, 2 <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">ἐκλαμβάνων</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span>, «levou cada pessoa de parte»); 9:2 (acrescentando <span class=\"greek\">μόνος</span>), 28; 13:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:10</a>; 10:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:2</a> (sobre a reunião separada, cf. Josefo, Bell. 2, 199 <span class=\"greek\">τ</span>. <span class=\"greek\">δυνατοὺς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κοινῷ</span> <span class=\"greek\">συλλέγων</span>; Apiano, Bell. Civ. 5, 40 §170); ISm 7:2.</p><p class=\"entry-text\">⑥ Referente a ser característico e distintivo de uma entidade: próprio de, peculiar a alguém. <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἰδίου</span> <span class=\"greek\">καρποῦ</span> <span class=\"greek\">γινώσκεται</span>, «cada árvore é reconhecida por seu próprio fruto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:44</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <span class=\"greek\">πρόβατα</span>, «suas próprias ovelhas», Jo 10:3s. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἴδιον</span>, «para o lugar que lhe é próprio» (o lugar ao qual pertencia), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:25</a>; cf. 20:28.</p><p class=\"entry-text\">A expressão <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐφείσατο</span>, «não poupou seu próprio Filho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:32</a>, enfatiza o caráter extraordinário da dádiva de Deus (a associação de Paulo com a referência à generosidade universal, <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">αὐτο͂ν</span>, acrescenta um componente semântico a <span class=\"greek\">ἰ</span>. nessa passagem; para o tema da generosidade universal, ver, por exemplo, OGI 339, 29s.; para a doação de recursos próprios, ibid. 104; IGR 739, II, 59–62. Para a expressão <span class=\"greek\">ὁ</span> <span class=\"greek\">ἴδιος</span> <span class=\"greek\">υἱός</span>, mas em contextos temáticos distintos, ver, por exemplo, Diodoro Sículo 17, 80, 1, sobre Parmênio; 17, 118, 1, sobre Antípatro. Relatando um caso em que um filho não foi poupado, Polieno 8, 13 usa <span class=\"greek\">υἱὸς</span> <span class=\"greek\">αὐτοῦ</span>, evidentemente sem ênfase, mas Exc. 3, 7 introduz <span class=\"greek\">ἴδιος</span> <span class=\"greek\">υἱός</span> para acentuar a gravidade da transgressão de uma ordem pelo próprio filho de um oficial).</p><p class=\"entry-text\">1Co 7:4ab. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἐν</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">τάγματι</span>, «cada um na sua própria ordem», 15:23 (cf. En 2:1 <span class=\"greek\">τ</span>. <span class=\"greek\">ἰ</span>. <span class=\"greek\">τάξιν</span>). <span class=\"greek\">καιροὶ</span> <span class=\"greek\">ἴδιοι</span>, «os tempos apropriados» (cf. Diodoro Sículo 1, 50, 7 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἰδίοις</span> <span class=\"greek\">χρόνοις</span>; semelhantemente 5, 80, 3; Josefo, Ant. 11, 171; Pseudo-Clemente, Hom. 3, 16; TestSol 6:3 <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">ἰ</span>.; Justino, D. 131, 4 <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">καιρῶν</span>; Melitão, P. 38, 258ss.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:6</a>; 6:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:3</a>; 1Cl 20:4; cf. 1Tm 3:4s., 12; 4:2; 5:4. <span class=\"greek\">ἴδιαι</span> <span class=\"greek\">λειτουργίαι</span> … <span class=\"greek\">ἴδιος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> … <span class=\"greek\">ἴδιαι</span> <span class=\"greek\">διακονίαι</span>, respectivamente «ministérios ... lugar ... serviços próprios», 1Cl 40:5.</p><p class=\"entry-text\">Em <span class=\"greek\">ἰδία</span> <span class=\"greek\">ἐπίλυσις</span>, «interpretação particular», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:20</a>, a interpretação de iniciativa pessoal contrasta com o sentido pretendido pelo próprio autor ou com a interpretação de outra pessoa autorizada ou competente (ver <span class=\"greek\">ἐπίλυσις</span> e W. Weeda, NThSt 2, 1919, 129–35). — Todas essas passagens estão próximas da acepção 3; é particularmente difícil delimitar suas fronteiras. — DELG; M-M; EDNT; TW; Spicq; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰδίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Advérbio de <span class=\"greek\">ἴδιος</span> (Platão e outros; Herão de Alexandria I p. 432, 4; SIG 1002, 13; Sb 17:10, variante de leitura; Fílon, Plant. 13; Migr. Abr. 50; Justino, A I, 22, 2 e outros [em oposição a <span class=\"greek\">κοινῶς</span>]; Atenágoras, R. 70, 15 e outros): «de modo especial», «especialmente», <span class=\"greek\">ἀγαπᾶν</span>, «amar», B 4:6; talvez <span class=\"greek\">ἰ</span>. se destine a estabelecer contraste com <span class=\"greek\">πάντας</span>, caso em que poderia significar «individualmente».</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0172-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰδιώτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἴδιος</span>; Heródoto e posteriores; empréstimo no hebraico rabínico.)</p><p class=\"entry-text\">① Pessoa relativamente inábil ou inexperiente em alguma atividade ou ramo do conhecimento: leigo, amador, em contraste com perito ou especialista de qualquer espécie (pessoa sem coroa, em contraste com rei [Heródoto 2, 81; 7, 199; EpArist 288s.; Fílon, Decal. 40; Josefo, Bell. 1, 665]; soldado raso, em contraste com oficial [Políbio 1, 69, 11]; em oposição a médico [Tucídides 2, 48, 3; Fílon, Conf. Lingu. 22], filósofo [Plutarco, Mor. 776e; Epicteto, índice Sch.; Fílon, Omn. Prob. Lib. 3; Justino, A II, 10, 8], orador [Isócrates 4, 11; Luciano, Jupp. Trag. 27], <span class=\"greek\">μάντις</span>, «adivinho» [Pausânias 2, 13, 7], poeta [Alexis Cômico 269; Platão, Laws 890a], sacerdote [OGI 90, 52; Fílon, Spec. Leg. 3, 134], pessoa instruída [Luciano, Lexiph. 25]: toda pessoa que não pertence a algum desses grupos. Civil em oposição a soldado [Josefo, Bell. 2, 178]; cidadão particular em oposição a agente público [Sb 3924, 9; 25; POxy 1409, 14]).</p><p class=\"entry-text\"><span class=\"greek\">ἰ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>, «inábil na fala» (cf. Josefo, Ant. 2, 271, acerca de Moisés, <span class=\"greek\">ἰ</span>. … <span class=\"greek\">λόγοις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:6</a> (W. Gemoll, PhilolWoch 52, ’32, 28; cf. W. Roberts, Longinus on the Sublime, 1899, 200, s.v. <span class=\"greek\">ἰδιώτης</span>). (Com <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἀγράμματος</span>), «pessoa sem instrução formal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:13</a> (Justino, A I, 39, 3; 60, 11; Atenágoras II, 3).</p><p class=\"entry-text\">② Pessoa que não possui conhecimento da experiência de determinado grupo: não iniciado, pessoa de fora. Em 1Co 14:23s., <span class=\"greek\">ἰδιῶται</span> e <span class=\"greek\">ἄπιστοι</span> formam juntos um contraste com a congregação cristã. Os <span class=\"greek\">ἰ</span>. não são equivalentes aos <span class=\"greek\">ἄπιστοι</span> (contra Lietzmann, Hdb., ad loc.), nem cristãos plenamente integrados, mas ocupam uma posição intermediária entre os grupos, provavelmente como possíveis futuros membros e, portanto, relativamente de fora.</p><p class=\"entry-text\">(<span class=\"greek\">ἰδιώτης</span> como termo técnico da vida religiosa, por exemplo, OGI 90, 52 [196 a.C.], SIG 1013, 6; inscrição dos mistérios de Andânia [92 a.C.]: SIG 736, 16–19 <span class=\"greek\">αἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἰδιώτιες</span> … <span class=\"greek\">αἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἱεραί</span>. Em associações religiosas o termo é usado para não membros que podem participar dos sacrifícios: F. Poland, Gesch. des griech. Vereinswesens, 1909, 247*; 422. — Cf. também Cratino, o Jovem, Cômico [séc. IV a.C.], Fgm. 7 vol. II 291 K., a respeito dos pitagóricos: <span class=\"greek\">ἔθος</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">αὐτοῖς</span>, <span class=\"greek\">ἂν</span> <span class=\"greek\">τιν</span>’ <span class=\"greek\">ἰδιώτην</span> <span class=\"greek\">ποθὲν</span> <span class=\"greek\">λάβωσιν</span> <span class=\"greek\">εἰσελθόντα</span> <span class=\"greek\">κτλ</span>.).</p><p class=\"entry-text\">A relação mais próxima que mantinham com o grupo cristão, em contraste com os <span class=\"greek\">ἄπιστοι</span> (assim já Severiano de Gábala [morto após 409 d.C.]: K. Staab, Pauluskommentare aus d. griech. Kirche, ’33, p. xxxv; 268), é claramente demonstrada pelo fato de ocuparem lugar específico no recinto de reunião dos cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:16</a> (P. Tomson, Paul and the Jewish Law [CRINT III/1], ’90, 142–44; <span class=\"greek\">ἀναπληρόω</span> 4). — DELG, s.v. <span class=\"greek\">ἴδιος</span>; M-M; TW; Spicq; Sv.</p></section></article>\n"};
